Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include<iostream>
#include<algorithm>
#include<string>
#include<vector>
#include<cstring>
#include<algorithm>

//#include<bits/stdc++.h>

using namespace std;


#ifdef ONLINE_JUDGE
	#define WAIT
#else
	#define WAIT cout<<flush, system("PAUSE")
#endif

#define FOR(IN,N) for(int I = IN;I < N;++I)
#define FORR(END,N) for(int I = N-1;I >= END;--I)
#define foreach(arr) for(auto item : arr)
#define REP(I,A,B) for(int I = A;I < B;++I)

#define CONTAINS(m,x) m.find(x) != m.end()
#define clr(x) memset((x),0,sizeof(x))
#define PB push_back
#define remove erase
#define ALL(v) v.begin(),v.end()
#define sz(a) a.size();
#define endl '\n'
#define MAX 10010

typedef long long i64;
typedef pair<int,int> pii;

//const int MOD = ;

string solve,s; int N;

void Check(){

	if(solve[0] == '.'){
		solve.remove(0,1);
		solve = "dot" + solve;
	}
	else if(solve[0] == '@'){
		solve.remove(0,1);
		solve = "at" + solve;
	}

	if(solve[solve.size() - 1] == '.'){
		solve.remove(solve.size() - 1,1);
		solve += "dot";
	}
	else if(solve[solve.size() - 1] == '@'){
		solve.remove(solve.size() - 1,1);
		solve += "at";
	}

}

int main()
{
	ios_base :: sync_with_stdio(0);
	cin.tie(0);

	cin >> s;

	N = sz(s);

	solve = "";

	for(int I = 0;I < N;++I){

		if(I + 3 <= N){
			if(s.substr(I,3) == "dot"){
				solve += ".";
				I+=2;
			}
			else{
				if(I + 2 <= N){
					if(s.substr(I,2) == "at"){
						solve += "@";
						I+=1;
					}
					else solve += s[I];
				}
				else solve += s[I];
			}
		}
		else if(I + 2 <= N){
			if(s.substr(I,2) == "at"){
				solve += "@";
				I+=1;
			}
			else solve += s[I];
		}
		else solve += s[I];
	}

	Check();

	int cont = 0;

	for(int I = 0;I < solve.size();++I){

		if(solve[I] == '@') ++cont;

	}

	if(cont == 1) cout << solve << endl;

	else{

		bool ok = 1;

		for(int I = 0;I < solve.size();++I){

			if(solve[I] == '@'){
				if(ok){
					cout << '@';
					ok = false;
				}
				else{
					cout << "at";
				}
				continue;
			}
			cout << solve[I];
		}
		cout << endl;
	}
}
